const grid=document.querySelector('#project-grid');
function renderProjects(filter='all'){const shown=projects.filter(p=>filter==='all'||p.categories.includes(filter));grid.innerHTML=shown.map(p=>`<button class="project-card" data-project="${p.id}" aria-label="View details: ${p.title}"><div class="project-image"><img src="assets/${p.thumbnail||p.image}" alt="${p.title} project preview" loading="${p.id==='ihoya'||filter!=='all'?'eager':'lazy'}" decoding="async"><span class="arrow">↗</span></div><div class="project-meta"><span>${p.type}</span><span>PROJECT DETAILS ↗</span></div><h3>${p.title}</h3><p>${p.subtitle}</p></button>`).join('');document.querySelector('#project-count').textContent=`Showing ${shown.length} ${shown.length===1?'project':'projects'}`}
renderProjects();
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProjects(b.dataset.filter)}));
const dialog=document.querySelector('#project-dialog');let lastCard;
grid.addEventListener('click',e=>{const card=e.target.closest('[data-project]');if(!card)return;lastCard=card;const p=projects.find(x=>x.id===card.dataset.project);document.querySelector('#dialog-content').innerHTML=`<span class="dialog-tag">${p.type}</span><h2 id="dialog-title">${p.title}</h2><div class="tags">${p.tech.map(t=>`<span>${t}</span>`).join('')}</div><img class="dialog-image" src="assets/${p.image}" alt="${p.title} project documentation"><p>${p.description}</p><h3>Role & process</h3><p>${p.role}</p><h3>Development highlights</h3><ul>${p.features.map(t=>`<li>${t}</li>`).join('')}</ul>${p.extra?`<img class="dialog-image" src="assets/${p.extra}" alt="iHoya distribution map and observation filters">`:''}${p.link?`<a class="button primary" href="${p.link}" target="_blank" rel="noopener">Read publication ↗</a>`:''}`;dialog.showModal();dialog.scrollTop=0});
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>lastCard?.focus());
const experiences={professional:[['February – July 2026','Machine Learning Lab Assistant','ITENAS Bandung','Guided students through data processing, visualization, preprocessing, and machine learning algorithms using Python. Supported project development and model evaluation.'],['February – July 2026','Game Programming Lab Assistant','ITENAS Bandung','Guided game development using Unity and C#, covering scripting, physics, animation, interfaces, debugging, and deployment to PC and WebGL.'],['October 2025 – January 2026','Multimedia Engineering Lab Assistant','ITENAS Bandung','Guided practical sessions in interactive multimedia and digital content production using Adobe Animate, including synchronous, asynchronous, and hybrid scenarios.'],['July – August 2025','Web Developer Intern — Human-Computer Interaction & Visualization','National Research and Innovation Agency (BRIN) · Internship · Bandung, West Java, Indonesia · Hybrid','Contributed as a full-stack developer to SISIRAJA, a geographic information system for the Lembang Fault and active faults in western Java. Developed interactive Leaflet maps with exploration from the national level to the West Java regional level. Built interactive news and scientific article features, including functionality to identify nearby schools in relation to active faults. Worked on both frontend and backend development to support the overall system.']],organization:[['January – December 2025','Head of Entrepreneurship Division','HMIF ITENAS','Led the planning and delivery of entrepreneurship programs, managed financial planning and business activities, and developed partnerships with external organizations.'],['July – December 2024','Public Relations Division Member','HMIF ITENAS','Maintained communication with external stakeholders, supported publicity for activities and achievements, and collaborated on social initiatives and partnerships.'],['August 2023 – June 2024','Facilities & Inventory Division Member','HMIF ITENAS','Managed inventory and equipment loan records, monitored asset condition, and coordinated the use and distribution of organizational facilities.']]};
function renderExperience(tab){document.querySelector('#timeline').innerHTML=experiences[tab].map((x,i)=>`<details class="timeline-item" ${i===0?'open':''}><summary><span class="date">${x[0]}</span><div class="role"><h3>${x[1]}</h3><span class="place">${x[2]}</span></div><span class="plus" aria-hidden="true">+</span></summary><div class="details">${x[3]}</div></details>`).join('')};renderExperience('professional');
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderExperience(b.dataset.tab)}));
document.querySelector('#menu').addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(open))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false')}));
document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('rizki.tazidi@gmail.com');status.textContent='Email copied to clipboard.'}catch{status.textContent='Email: rizki.tazidi@gmail.com — select the text to copy it.'}});
